private void pop(final String descriptor){
    // Implementation of the method
    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, find the end of the argument types
        index = descriptor.indexOf(')');
        String argumentTypes = descriptor.substring(1, index);
        for (char c : argumentTypes.toCharArray()) {
            switch (c) {
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    // These types take up one slot
                    popOneSlot();
                    break;
                case 'D':
                case 'J':
                    // These types take up two slots
                    popTwoSlots();
                    break;
                case 'L':
                case '[':
                    // Reference types take up one slot
                    popOneSlot();
                    // Skip the rest of the object or array descriptor
                    while (descriptor.charAt(index) != ';') {
                        index++;
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
        }
    } else {
        // It's a field descriptor
        switch (descriptor.charAt(0)) {
            case 'B':
            case 'C':
            case 'F':
            case 'I':
            case 'S':
            case 'Z':
                popOneSlot();
                break;
            case 'D':
            case 'J':
                popTwoSlots();
                break;
            case 'L':
            case '[':
                popOneSlot();
