final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int utf8Index = constantPoolEntryIndex * 8 + 1; // Assuming each entry is 8 bytes and the first byte is the tag
    int length = (classFileBuffer[utf8Index] & 0xFF) << 8 | (classFileBuffer[utf8Index + 1] & 0xFF);
    int charIndex = 0;
    for (int i = 0; i < length; ) {
        int c = classFileBuffer[utf8Index + 2 + i] & 0xFF;
        switch (c >> 4) {
            case 0: case 1: case 2: case 3: case 4: case 5: case 6: case 7:
                // 0xxxxxxx
                charBuffer[charIndex++] = (char) c;
                i++;
                break;
            case 12: case 13:
                // 110xxxxx 10xxxxxx
                charBuffer[charIndex++] = (char) (((c & 0x1F) << 6) | (classFileBuffer[utf8Index + 3 + i] & 0x3F));
                i += 2;
                break;
            case 14:
                // 1110xxxx 10xxxxxx 10xxxxxx
                charBuffer[charIndex++] = (char) (((c & 0x0F) << 12) | ((classFileBuffer[utf8Index + 3 + i] & 0x3F) << 6) | (classFileBuffer[utf8Index + 4 + i] & 0x3F));
                i += 3;
                break;
            default:
                // Invalid UTF-8 sequence
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
    }
    return new String(charBuffer, 0, charIndex);
}

