            // Object type, skip to the end of the class name
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            // Pop one from the stack
            break;
        case '[':
            // Array type, skip to the end of the array descriptor
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            // After the '['s, there should be a type descriptor
            index = popType(descriptor, index) - 1;
            // Pop one from the stack
            break;
    }
    return index + 1;
}

