public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = parseThreadSnapshot(line);
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (snapshot.getTimestamp() >= range.getStartTime() && snapshot.getTimestamp() <= range.getEndTime()) {
                    snapshots.add(snapshot);
                    break;
                }
            }
        }
    }
    return snapshots;
}

private static ThreadSnapshot parseThreadSnapshot(String line) {
    // Assuming the line is comma-separated and contains timestamp, threadId, and other relevant data
    String[] parts = line.split(",");
    long timestamp = Long.parseLong(parts[0]);
    int threadId = Integer.parseInt(parts[1]);
    // Parse other fields as necessary
    return new ThreadSnapshot(timestamp, threadId);
}
